    uniqueId: 'cat1',
    questions: [
      { uniqueId: 'q1' },
      { uniqueId: 'q2' }
    ]
  },
  {
    uniqueId: 'cat2',
    questions: [
      { uniqueId: 'q3' },
      { uniqueId: 'q4' }
    ]
  }
];

console.log(createQIdMap(catData));
