```js
const express = require('express');
const bodyParser = require('body-parser');
const mongoose = require('mongoose');
const Topic = require('./path/to/your/topicModel'); // Adjust the path to your topic model

const app = express();
const port = process.env.PORT || 3000;

// Middleware
app.use(bodyParser.json());

// Connect to MongoDB
mongoose.connect('mongodb://localhost:27017/yourdbname', {
  useNewUrlParser: true,
  useUnifiedTopology: true,
  useCreateIndex: true
});

const db = mongoose.connection;
db.on('error', console.error.bind(console, 'connection error:'));
db.once('open', () => {
  console.log('Connected to MongoDB');
});

// POST endpoint to search topics
app.post('/search', async (req, res) => {
  const { searchString } = req.body;

  if (!searchString) {
    return res.status(400).json({ error: 'searchString is required' });
  }

  try {
    const regex = new RegExp(searchString, 'i'); // 'i' for case insensitive
    const topics = await Topic.find({
      $or: [
        { name: { $regex: regex } },
        { description: { $regex: regex } }
      ]
    });

    res.json(topics);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'An error occurred while searching for topics' });
  }
});

// Start the server
app.listen(port, () => {
  console.log(`Server is running on port ${port}`);
});
```

In the code above:
- We set up an Express server and connect to a MongoDB database using Mongoose.
- The `/search` endpoint accepts a `searchString` from the request body.
- We use a regular expression to perform a case-insensitive search on the `name` and `description` fields of the `Topic` model.
- Matching topics are returned in the response.

Replace `'mongodb://localhost:27017/yourdbname'` with your actual MongoDB connection string.

