Here's the updated code:

```javascript
function parseTextToLineArray(text) {
    const lines = text.split('\n');
    const lineArray = lines.map(line => {
        const trimmedLine = line.trim();
        const leadingWhitespace = line.match(/^[ \t]*/)[0];
        const indentationLevel = leadingWhitespace.length; // This counts both spaces and tabs

        return {
            name: trimmedLine,
            indentationLevel: indentationLevel
        };
    });
    return lineArray;
}

// Example usage:
const text = `
  Root
    Child 1
\t  Subchild 1
    Child 2
`;

const lineArray = parseTextToLineArray(text);
console.log(lineArray);
```

