from flask import Flask, request, jsonify
from flask_pymongo import PyMongo
from flask_cors import CORS

app = Flask(__name__)
app.config['MONGO_URI'] = 'mongodb://localhost:27017/tagsdb'
mongo = PyMongo(app)
CORS(app)

# Create a new tag
@app.route('/tags', methods=['POST'])
def create_tag():
    try:
        data = request.get_json()
        tags_collection = mongo.db.tags
        tags_collection.insert_one(data)
        return jsonify({'message': 'Tag created successfully'}), 201
    except Exception as e:
        return jsonify({'message': 'Error creating tag', 'error': str(e)}), 500

# Read all tags
@app.route('/tags', methods=['GET'])
def get_tags():
    try:
        tags_collection = mongo.db.tags
        tags = list(tags_collection.find({}, {'_id': False}))
        return jsonify({'tags': tags}), 200
    except Exception as e:
