import org.springframework.data.mongodb.repository.MongoRepository;
import org.springframework.data.mongodb.repository.Query;

import java.util.List;

public interface DataElementRepository extends MongoRepository<DataElement, String> {

    @Query("{$group: {_id: '$tags', count: {$sum: 1}}}")
    List<TagCountProjection> getTagCounts();

    interface TagCountProjection {
        List<String> getId();
        long getCount();
    }
}
```

2. **Create Controller**:
   Update the `TagController` class to define the new endpoint.

```java
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.stream.Collectors;

@RestController
@RequestMapping("/api/tags")
public class TagController {

    private final DataElementRepository dataElementRepository;

    @Autowired
    public TagController(DataElementRepository dataElementRepository) {
        this.dataElementRepository = dataElementRepository;
    }

    @GetMapping("/list")
    public List<TagCountResponse> getTagListWithCounts() {
        List<DataElementRepository.TagCountProjection> tagCounts = dataElementRepository.getTagCounts();

        return tagCounts.stream()
                .map(tagCountProjection -> new TagCountResponse(tagCountProjection.getId().get(0), tagCountProjection.getCount()))
                .collect(Collectors.toList());
    }
}
```

