interface SilverPriceDataProvider {
    String fetchSilverPriceData() throws IOException;
}

class RestSilverPriceDataProvider implements SilverPriceDataProvider {
    private static final String API_URL = "https://api.example.com/silver-prices";

    @Override
    public String fetchSilverPriceData() throws IOException {
        URL url = new URL(API_URL);
        InputStream inputStream = url.openStream();
        try (Scanner scanner = new Scanner(inputStream, StandardCharsets.UTF_8)) {
            return scanner.useDelimiter("\\A").next();
        }
    }
}

interface SilverPriceDataParser {
    DefaultXYDataset parseData(String json);
}

class JsonSilverPriceDataParser implements SilverPriceDataParser {
    @Override
    public DefaultXYDataset parseData(String json) {
        DefaultXYDataset dataset = new DefaultXYDataset();
        JSONArray dataArray = new JSONArray(json);
        double[][] data = new double[2][dataArray.length()];

        for (int i = 0; i < dataArray.length(); i++) {
            JSONObject entry = dataArray.getJSONObject(i);
            double timestamp = entry.getDouble("timestamp");
            double price = entry.getDouble("price");
            data[0][i] = timestamp;
            data[1][i] = price;
        }

        dataset.addSeries("Silver Price", data);

        return dataset;
    }
}

