Here's an example of how you can create a Swing application that fetches silver price data and displays it as a basic line chart using the JFreeChart library:

```java
import org.jfree.chart.ChartFactory;
import org.jfree.chart.ChartFrame;
import org.jfree.chart.ChartPanel;
import org.jfree.chart.JFreeChart;
import org.jfree.chart.plot.PlotOrientation;
import org.jfree.data.xy.DefaultXYDataset;
import org.json.JSONArray;
import org.json.JSONObject;

import javax.swing.*;
import java.awt.*;
import java.io.IOException;
import java.io.InputStream;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.Scanner;

public class SilverPriceChartApp extends JFrame {

    private static final String API_URL = "https://api.example.com/silver-prices";

    public SilverPriceChartApp() {
        setTitle("Silver Price Chart");
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setSize(800, 600);
        setLocationRelativeTo(null);

        try {
            String json = fetchSilverPriceData();
            DefaultXYDataset dataset = createDatasetFromJson(json);
            JFreeChart chart = createChart(dataset);
            ChartPanel chartPanel = new ChartPanel(chart);
            add(chartPanel, BorderLayout.CENTER);
        } catch (IOException e) {
            e.printStackTrace();
            JOptionPane.showMessageDialog(this, "Failed to fetch data: " + e.getMessage(), "Error", JOptionPane.ERROR_MESSAGE);
        }
    }

    private String fetchSilverPriceData() throws IOException {
        URL url = new URL(API_URL);
        InputStream inputStream = url.openStream();
        try (Scanner scanner = new Scanner(inputStream, StandardCharsets.UTF_8)) {
            return scanner.useDelimiter("\\A").next();
        }
    }

    private DefaultXYDataset createDatasetFromJson(String json) {
        DefaultXYDataset dataset = new DefaultXYDataset();
        JSONArray dataArray = new JSONArray(json);
        double[][] data = new double[2][dataArray.length()];

        for (int i = 0; i < dataArray.length(); i++) {
            JSONObject entry = dataArray.getJSONObject(i);
            double timestamp = entry.getDouble("timestamp");
            double price = entry.getDouble("price");
            data[0][i] = timestamp;
            data[1][i] = price;
        }

        dataset.addSeries("Silver Price", data);

        return dataset;
    }

    private JFreeChart createChart(DefaultXYDataset dataset) {
        return ChartFactory.createXYLineChart(
                "Silver Price Chart",
                "Timestamp",
                "Price",
                dataset,
                PlotOrientation.VERTICAL,
                true,
                true,
                false
        );
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            SilverPriceChartApp app = new SilverPriceChartApp();
            app.setVisible(true);
        });
    }
}
```

