        index: true,
        element: "WelcomeIndex"
      },
      {
        path: "old-dashboard",
        element: "ResumeDashboard"
      },
      {
        path: "resumes",
        element: "Child2"
      }
    ]
  },
  {
    path: "*",
    element: "NotFound"
  }
];

const componentMap = {
  Parent: BaseComponent,
  WelcomeIndex: WelcomeIndex,
  ResumeDashboard: ResumeDashboard,
  Child2: Child2,
  NotFound: NotFound
};

const generateRoutes = (config = routeConfig) => {
  return config.map((route, index) => {
    const Element = componentMap[route.element];
    if (route.children) {
      return (
        <Route key={index} path={route.path} element={<Element />}>
          {route.children.map((child, idx) => {
            const ChildElement = componentMap[child.element];
            return child.index ? (
              <Route key={idx} index element={<ChildElement />} />
            ) : (
              <Route key={idx} path={child.path} element={<ChildElement />} />
            );
          })}
        </Route>
      );
    }
    return <Route key={index} path={route.path} element={<Element />} />;
  });
};

const App = () => {
  return (
    <Router>
      <Routes>
        {generateRoutes(routeConfig)}
      </Routes>
    </Router>
  );
};

export default App;
```

### Explanation:
1. **Parent Component**:
   - `BaseComponent` uses `useLocation` to get the current pathname.
   - The current path is logged and displayed, which helps in determining the selected child route.

2. **Routing Setup**:
   - The `routeConfig` array defines the routes and maps components to them.
   - `generateRoutes` function dynamically generates the routes based on the `routeConfig`.

3. **Child Components**:
   - Example child components (`WelcomeIndex`, `ResumeDashboard`, `Child2`) are simple functional components.

With this setup, the `BaseComponent` can determine which child route is currently selected by checking the `currentPath`.

