// Import your components
import Parent from './Parent';
import Child1 from './Child1';
import Child2 from './Child2';

// Define a mapping from string to component
const componentMap = {
  Parent: Parent,
  Child1: Child1,
  Child2: Child2
};

const routeConfig = [
  {
    path: "/",
    element: "Parent",
    children: [
      {
        path: "child1",
        element: "Child1"
